(1232, 'interfaces-web-22', 'Sustituyen por completo a HTML5 y eliminan el árbol DOM', FALSE),
(1233, 'interfaces-web-23', 'Son sinónimos exactos: MP3 es un códec de vídeo 4K y PNG es un contenedor de audio', FALSE),
(1234, 'interfaces-web-23', 'El contenedor (.mp4, .webm) es el archivo que empaqueta pistas de vídeo, audio y metadatos, mientras que el códec (H.264, VP9, AV1, AAC, Opus) es el algoritmo que comprime y descomprime cada flujo; suele combinarse WebM (VP9/AV1 + Opus) con respaldo en MP4 (H.264 + AAC)', TRUE),
(1235, 'interfaces-web-23', 'El navegador solo puede reproducir archivos .avi sin comprimir', FALSE),
(1236, 'interfaces-web-23', 'El códec es la etiqueta HTML `<video>` y el contenedor es el atributo `controls`', FALSE),
(1237, 'interfaces-web-24', 'Subtítulos en archivos ejecutables .exe e imágenes mediante tablas anidadas', FALSE),
(1238, 'interfaces-web-24', 'Subtítulos en formato WebVTT (`.vtt`) dentro de `<track kind="captions" ...>`, e imágenes adaptativas mediante los atributos `srcset` y `sizes` o el elemento `<picture>`', TRUE),
