(1241, 'interfaces-web-25', 'Porque impiden aplicar estilos con CSS', FALSE),
(1242, 'interfaces-web-25', 'Porque el navegador gestiona de serie su semántica, estado abierto/cerrado, interacción con teclado (como cerrar `<dialog>` con Escape) y exposición en el árbol de accesibilidad sin sobrecargar JavaScript', TRUE),
(1243, 'interfaces-web-25', 'Porque solo funcionan en Internet Explorer 6', FALSE),
(1244, 'interfaces-web-25', 'Porque descargan automáticamente una base de datos SQL en el cliente', FALSE),
